<script setup lang="ts">import {ref,onMounted,watch} from 'vue';import {api} from '../../api';import {locale,t} from '../../locales';import '../../styles/app.scss';const rows=ref<any[]>([]);const loading=ref(true);async function load(){loading.value=true;try{rows.value=await api.markets()}finally{loading.value=false}}onMounted(load);watch(locale,load)</script>
<template><view class="inner-page"><view class="inner-nav"><text class="back" @click="uni.navigateBack()">‹</text><text class="nav-title">{{t('完整行情')}}</text></view><view class="inner-main"><view class="inner-heading">{{t('市场行情')}}</view><view class="inner-subtitle">{{t('实时追踪主要交易对的 24 小时变化')}}</view><view v-if="loading" class="inner-card empty-state">{{t('加载中...')}}</view><view v-else-if="!rows.length" class="inner-card empty-state">{{t('暂无行情')}}</view><view v-else class="market-list"><view v-for="row in rows" :key="row[0]" class="market-row"><view class="market-symbol"><view class="market-avatar">{{row[0].split('/')[0].slice(0,1)}}</view><view><text class="list-title">{{row[0]}}</text><text class="list-meta">{{t('24 小时')}}</text></view></view><view class="market-value"><text>{{row[1]}}</text><text :class="row[2].startsWith('+')?'up':'down'">{{row[2]}}</text></view></view></view></view></view></template>
<style scoped>.market-list{margin-top:22rpx;overflow:hidden;background:#fff;border:1rpx solid var(--cf-line);border-radius:13rpx}.market-row{display:flex;align-items:center;justify-content:space-between;padding:18rpx 16rpx;border-bottom:1rpx solid #F1F5F9}.market-row:last-child{border-bottom:0}.market-symbol,.market-value{display:flex;align-items:center;gap:12rpx}.market-value{flex-direction:column;align-items:flex-end;gap:3rpx;font-size:21rpx;font-weight:700}.market-avatar{display:grid;place-items:center;width:42rpx;height:42rpx;border-radius:50%;background:#EFF6FF;color:var(--cf-brand);font-weight:800}</style>
